import numpy as np
def equation(t, x, v, params):
    w = params[0]
    C = np.cos(w*t); S = np.sin(w*t)
    base = params[1] + params[2]*x + params[3]*v + params[4]*x*x + params[5]*v*np.abs(v) + params[6]*np.sin(x) + params[7]*x*v
    return base + (params[8] + params[9]*x + 0.0*v)*C + (0.0*x + 0.0*v + 0.0)*S + 0.0*np.sin(x)
